import{z as d,x as A,o as n,c as p,q as s,j as E,D as e,d as o,s as l,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"倒排与全文","description":"","frontmatter":{"title":"倒排与全文","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inverted-index-fulltext.md","filePath":"cs/inverted-index-fulltext.md","lastUpdated":1791063341000}'),B={name:"cs/inverted-index-fulltext.md"};function D(c,a,f,g,m,u){const i=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="倒排与全文" tabindex="-1">倒排与全文 <a class="header-anchor" href="#倒排与全文" aria-label="Permalink to &quot;倒排与全文&quot;">​</a></h1><div class="epigraph"><p>倒排表从词项指向出现位置；全文检索是查询该表，不是 `LIKE &#39;%x%&#39;` 扫堆。</p><footer>—— 据 Manning, Raghavan and Schütze, Introduction to IR； Zobel and Moffat 倒排索引；数据库 GIN/全文实践</footer></div><p><a href="/cs/bitmap-index">上一课</a>用值→行位图。本课不 AND 维值。缺口是文本：词项多、文档长、要短语与排名。倒排索引（inverted index）：词典 + 每个词的 posting（文档 id、词频、位置）。关系库用 GIN/GiST 或外置搜索引擎；本课机制，产品课在后课搜索引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>LIKE &#39;%foo%&#39;</code> 不能用 B+ 前缀。全文：分词、停用词、词干，再查 posting 交。短语：位置相邻。缺口是<strong>把文档当分析对象</strong>，行是文档或文档碎片。更新：文档改则要改多个 posting，写放大类似位图但 NDV（词表）极大，常用 LSM 或段+不可变（Lucene 谱系）。</p><p>排名（TF-IDF、BM25）在 posting 上算，不是 SQL <code>ORDER BY length</code>。与向量检索后课不同：这里是稀疏词空间，不是稠密嵌入。</p><p><span class="marginnote">Manning et al. IR 教材。Zobel and Moffat 倒排综述。PostgreSQL tsvector/GIN、InnoDB 全文是库内子集。本课不教语言学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建索引：分词 → 写 posting，压缩差量文档 id。查询：解析查询串 → 取 posting → 交/并/位置过滤 → 打分截断。与 SQL：谓词 <code>@@</code> 下推成倒排扫描，再回表取行。</p><p>事务：库内全文要进同一事务，恢复与 WAL 对齐；外置引擎常最终一致，CDC 后课。</p>',10)),(n(),E(r,null,{default:e(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E6%96%87%E6%A1%A3%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%22%5D%0A%20%20TOK%20--%3E%20INV%5B%22%E8%AF%8D%E9%A1%B9%E5%88%B0%20posting%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20POST%5B%22%E5%8F%96%20posting%20%E4%BA%A4%22%5D%0A%20%20POST%20--%3E%20RANK%5B%22%E6%89%93%E5%88%86%22%5D%0A%20%20RANK%20--%3E%20HEAP%5B%22%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"段：不可变倒排段，查询时多段堆归并，后台合并——LSM 思想在搜索里。zone/跳过：对文档 id 范围可跳过。延迟物化：先 id 再取标题列。",-1)),a[5]||(a[5]=t("p",null,"与位图：低 NDV 可用位图当 posting；词项 posting 通常是压缩整数列。",-1)),(n(),E(r,null,{default:e(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%3A%20%E6%90%9C%E7%B4%A2%20%E5%BC%95%E6%93%8E%22%5D%20--%3E%20P1%5B%22%E8%AF%8D%E9%A1%B9%3A%20%E6%90%9C%E7%B4%A2%22%5D%0A%20%20Q%20--%3E%20P2%5B%22%E8%AF%8D%E9%A1%B9%3A%20%E5%BC%95%E6%93%8E%22%5D%0A%20%20P1%20--%3E%20AND%5B%22posting%20%E6%B1%82%E4%BA%A4%20(%E5%B7%AE%E9%87%8Fid%E5%AF%B9%E6%92%9E)%22%5D%0A%20%20P2%20--%3E%20AND%0A%20%20AND%20--%3E%20POS%5B%22%E4%BD%8D%E7%BD%AE%E8%BF%87%E6%BB%A4%3A%20%E7%9B%B8%E9%82%BB%E6%89%8D%E7%AE%97%E7%9F%AD%E8%AF%AD%22%5D%0A%20%20POS%20--%3E%20IDS%5B%22%E5%80%99%E9%80%89%E6%96%87%E6%A1%A3%20id%20%E5%88%97%E8%A1%A8%22%5D%0A%20%20IDS%20--%3E%20FETCH%5B%22%E5%9B%9E%E8%A1%A8%E5%8F%96%E6%A0%87%E9%A2%98%E6%AD%A3%E6%96%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：查短语 <code>&quot;数据库索引&quot;</code>，100 万篇文档里「数据库」出现在 8 万篇、「索引」出现在 6 万篇，先求交得 1.2 万篇共现；再做位置过滤（两个词的 posting 位置必须恰好相邻），可能只剩 300 篇——短语查询的精确性全靠 posting 里多存的位置列。</span></p><p><span class="marginnote">直觉类比：倒排索引就是书末的「索引页」——先在索引页查到关键词在第几页，再翻那几页；<code>LIKE &#39;%x%&#39;</code> 则相当于一页一页把整本书重读一遍找关键词，文档越多越慢。</span></p><p><span class="marginnote">常见误区：初学者容易以为改一个文档只动一行索引。实际上该文档每个词都要从对应 posting 里增删，是「一个写带动 N 个词表」的写放大——这正是搜索引擎普遍用不可变段加后台合并、而不是原地更新的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 R 树。也不把向量 ANN 当全文。通配与正则另有三gram 倒排变体，点名。</p><p>后课默认：全文走倒排，不要前导百分号 LIKE。空间索引：几何对象的选择率与邻接，结构换成 R 树等。</p><p>倒排回答「哪些文档含这些词」；关系谓词仍在回表后做。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>倒排是词项→位置列表；全文查询是交并与打分。</li><li>更新走段合并或 LSM，与行锁粒度不同。</li><li>空间索引下一课：几何过滤用另一族树。</li><li>出处：Manning et al.；Zobel and Moffat；库内 GIN 实践。</li></ul>',9))])}const S=d(B,[["render",D]]);export{x as __pageData,S as default};
